		{ profile: "gpt", requestCount: 1, tokensIn: 100, tokensOut: 50, totalCost: 0.015 },
	],
	currentEffectiveMode: "code",
	currentEffectiveProfile: "qwen",
	currentEffectiveModelId: "qwen-max",
