				// Check if code block is partially visible before allowing copy
				const codeBlock = codeBlockRef.current
				if (!codeBlock || codeBlock.getAttribute("data-partially-visible") !== "true") {
					return
				}
				const textToCopy = rawSource !== undefined ? rawSource : source || ""
				if (textToCopy) {
					copyWithFeedback(textToCopy, e)
				}
			},
			[source, rawSource, copyWithFeedback],
		)

		if (source?.length === 0) {
			return null
		}

		return (
			<CodeBlockContainer ref={codeBlockRef}>
				<MemoizedStyledPre
					preRef={preRef}
					preStyle={preStyle}
					wordWrap={wordWrap}
					windowShade={windowShade}
					collapsedHeight={collapsedHeight}
					highlightedCode={highlightedCode}
					updateCodeBlockButtonPosition={updateCodeBlockButtonPosition}
				/>
				{!isSelecting && (
					<CodeBlockButtonWrapper
						ref={copyButtonWrapperRef}
						onMouseOver={() => updateCodeBlockButtonPosition()}
						style={{ gap: 0 }}>
						{showCollapseButton && (
							<StandardTooltip
								content={t(`chat:codeblock.tooltips.${windowShade ? "expand" : "collapse"}`)}
								side="top">
								<CodeBlockButton
									onClick={() => {
										// Get the current code block element
										const codeBlock = codeBlockRef.current // Capture ref early
										// Toggle window shade state
										setWindowShade(!windowShade)

										// Clear any previous timeouts
										if (collapseTimeout1Ref.current) clearTimeout(collapseTimeout1Ref.current)
										if (collapseTimeout2Ref.current) clearTimeout(collapseTimeout2Ref.current)

										// After UI updates, ensure code block is visible and update button position
										collapseTimeout1Ref.current = setTimeout(
											() => {
												if (codeBlock) {
													// Check if codeBlock element still exists
													codeBlock.scrollIntoView({ behavior: "smooth", block: "nearest" })

													// Wait for scroll to complete before updating button position
													collapseTimeout2Ref.current = setTimeout(() => {
														// updateCodeBlockButtonPosition itself should also check for refs if needed
														updateCodeBlockButtonPosition()
														collapseTimeout2Ref.current = null
													}, 50)
												}
												collapseTimeout1Ref.current = null
											},
											WINDOW_SHADE_SETTINGS.transitionDelayS * 1000 + 50,
										)
									}}>
									{windowShade ? <ChevronDown size={16} /> : <ChevronUp size={16} />}
								</CodeBlockButton>
							</StandardTooltip>
						)}
						<StandardTooltip content={t("chat:codeblock.tooltips.copy_code")} side="top">
							<CodeBlockButton onClick={handleCopy}>
								{showCopyFeedback ? <Check size={16} /> : <Copy size={16} />}
							</CodeBlockButton>
						</StandardTooltip>
					</CodeBlockButtonWrapper>
				)}
			</CodeBlockContainer>
		)
	},
)

// Memoized content component to prevent unnecessary re-renders of highlighted code
const MemoizedCodeContent = memo(({ children }: { children: React.ReactNode }) => <>{children}</>)

// Memoized StyledPre component
const MemoizedStyledPre = memo(
	({
		preRef,
		preStyle,
		wordWrap,
		windowShade,
		collapsedHeight,
		highlightedCode,
		updateCodeBlockButtonPosition,
	}: {
		preRef: React.RefObject<HTMLDivElement>
		preStyle?: React.CSSProperties
		wordWrap: boolean
		windowShade: boolean
		collapsedHeight?: number
		highlightedCode: React.ReactNode
		updateCodeBlockButtonPosition: (forceHide?: boolean) => void
	}) => (
		<StyledPre
			ref={preRef}
			preStyle={preStyle}
			wordwrap={wordWrap ? "true" : "false"}
			windowshade={windowShade ? "true" : "false"}
			collapsedHeight={collapsedHeight}
			onMouseDown={() => updateCodeBlockButtonPosition(true)}
			onMouseUp={() => updateCodeBlockButtonPosition(false)}>
			<MemoizedCodeContent>{highlightedCode}</MemoizedCodeContent>
		</StyledPre>
	),
)

export default CodeBlock

import { useCallback, useEffect, useRef, useState, type MouseEvent } from "react"
import styled from "styled-components"
import { useAppTranslation } from "@src/i18n/TranslationContext"
import { useExtensionState } from "@src/context/ExtensionStateContext"
import { useCopyToClipboard } from "@src/utils/clipboard"
import { loadDesmos } from "@src/utils/desmosLoader"
import type { DesmosCalculator, DesmosConfig } from "@src/types/desmos"
import { useTheme } from "@src/themes/ThemeProvider"

interface DesmosBlockProps { code: string }

function toFallbackConfig(source: string): DesmosConfig | null {
	const withoutDelimiters = source
		.trim()
		.replace(/^\[\s*/, "")
		.replace(/\s*\]$/, "")
		.replace(/^\\\[\s*/, "")
		.replace(/\s*\\\]$/, "")
		.trim()
	const afterLabel = withoutDelimiters.replace(/^.*?[：:]\s*/, "").trim()
	const unwrapped = afterLabel.replace(/^\((.*)\)\s*[。；;]?$/s, "$1").trim()
	const equation = /[a-zA-Z]\s*=\s*[^。；;\n]+/.exec(unwrapped)?.[0]?.trim()
	const latex = equation || (/^[^\s]+$/.test(unwrapped) ? unwrapped : "")

	if (!latex || !/[=<>]/.test(latex)) return null

	// A response such as y=x^a=x^(1/b) is explanatory notation, not a Desmos
	// expression. Retain the first actual equation so Desmos can graph it.
	const parts = latex.split("=")
	const normalizedLatex = parts.length > 2 ? `${parts[0]}=${parts[1]}` : latex
	return { version: 1, expressions: [{ latex: normalizedLatex }] }
}

function parseConfig(code: string): DesmosConfig {
	const normalizedCode = code.trim().replace(/^```(?:json|desmos)?\s*/i, "").replace(/\s*```$/i, "").trim()
	let value: unknown
	try {
		value = JSON.parse(normalizedCode)
	} catch {
		// Models occasionally emit a raw LaTeX expression inside a `desmos`
		// fence instead of the JSON protocol. Accept that form as a safe fallback
		// so a valid curve is still rendered rather than showing a schema error.
		value = toFallbackConfig(normalizedCode)
		if (!value) throw new globalThis.Error("invalid Desmos JSON or LaTeX expression")
	}
	if (value === null || typeof value !== "object") {
		throw new globalThis.Error("Desmos block must contain a JSON object, not null or a primitive value")
	}
	const config = value as Partial<DesmosConfig>
	if (config.version !== 1 || !Array.isArray(config.expressions) || config.expressions.length === 0) {
		throw new globalThis.Error("version must be 1 and expressions must be a non-empty array")
	}
	for (const expression of config.expressions) {
		if (!expression || typeof expression.latex !== "string" || !expression.latex.trim()) {
			throw new globalThis.Error("each expression must contain a non-empty latex string")
		}
	}
	return config as DesmosConfig
}

function preserveJellyfishColor(color: string | undefined, jellyfish: boolean): string | undefined {
	if (!color || !jellyfish || !/^#[0-9a-f]{6}$/i.test(color)) return color

	const red = 255 - Number.parseInt(color.slice(1, 3), 16)
	const green = 255 - Number.parseInt(color.slice(3, 5), 16)
	const blue = 255 - Number.parseInt(color.slice(5, 7), 16)
	return `#${[red, green, blue].map((channel) => channel.toString(16).padStart(2, "0")).join("")}`
}

function isParametricExpression(latex: string): boolean {
	return /^\s*\([^,]+,/.test(latex)
}

export default function DesmosBlock({ code }: DesmosBlockProps) {
	const { desmosScriptUri } = useExtensionState()
	const { t } = useAppTranslation()
	const { themeId } = useTheme()
	const { copyWithFeedback, showCopyFeedback } = useCopyToClipboard()
	const containerRef = useRef<HTMLDivElement>(null)
	const calculatorRef = useRef<DesmosCalculator | null>(null)
	const [config, setConfig] = useState<DesmosConfig | null>(null)
	const [error, setError] = useState<string | null>(null)
	const [expanded, setExpanded] = useState(() => {
		try { return parseConfig(code).display?.defaultMode === "expanded" } catch { return false }
	})
	const [editedState, setEditedState] = useState<unknown>(null)
	const editable = config?.display?.editable !== false
	const jellyfish = themeId === "jellyfish"
	// Desmos' invertedColors mode inverts expression colors as well as the
	// canvas. Feed it complementary neon colors so the rendered result stays
	// maximally bright cyan/pink/purple/green/yellow.
	const jellyfishColors = ["#FF0A00", "#00D429", "#4BB200", "#FF0063", "#0019FF"]

	useEffect(() => {
		try { setConfig(parseConfig(code)); setError(null) }
		catch (cause) { setConfig(null); setError(cause instanceof globalThis.Error ? cause.message : String(cause)) }
	}, [code])

	useEffect(() => {
		if (!config || !containerRef.current) return
		let disposed = false
		let calculator: DesmosCalculator | undefined
		void loadDesmos(desmosScriptUri).then((Desmos) => {
			if (disposed || !containerRef.current) return
			calculator = Desmos.GraphingCalculator(containerRef.current, {
				// These are constructor options in the bundled Desmos API. Recreating
				// the calculator when the mode changes ensures the native expression
				// editor is actually mounted, instead of only changing the canvas size.
				keypad: expanded && editable,
				expressions: expanded && editable,
				settingsMenu: expanded,
				zoomButtons: true,
			})
			calculatorRef.current = calculator
			config.expressions.forEach((expression, index) => {
				const parametricDomain =
					expression.parametricDomain && isParametricExpression(expression.latex)
						? {
							min: String(expression.parametricDomain.min),
							max: String(expression.parametricDomain.max),
						}
						: undefined
				const desmosExpression: Parameters<DesmosCalculator["setExpression"]>[0] = {
					id: expression.id || `expression-${index + 1}`,
					latex: expression.latex,
				}
				const color = preserveJellyfishColor(
					expression.color || (jellyfish ? jellyfishColors[index % jellyfishColors.length] : undefined),
					jellyfish,
				)

				if (color) desmosExpression.color = color
				if (expression.hidden !== undefined) desmosExpression.hidden = expression.hidden
				if (expression.label) {
					desmosExpression.label = expression.label
					desmosExpression.showLabel = true
				}
				if (parametricDomain) desmosExpression.parametricDomain = parametricDomain

				calculator!.setExpression(desmosExpression)
			})
			config.expressions.forEach((expression, index) => {
				if (!expression.slider) return
				const sliderBounds: NonNullable<Parameters<DesmosCalculator["setExpression"]>[0]["sliderBounds"]> = {
					min: String(expression.slider.min),
					max: String(expression.slider.max),
				}
				if (expression.slider.step !== undefined) sliderBounds.step = String(expression.slider.step)
				calculator!.setExpression({
					id: `${expression.id || `expression-${index + 1}`}-slider`,
					latex: `${expression.slider.variable}=${expression.slider.value ?? expression.slider.min}`,
					sliderBounds,
				})
			})
			if (config.viewport) calculator.setMathBounds({ left: config.viewport.xmin, right: config.viewport.xmax, bottom: config.viewport.ymin, top: config.viewport.ymax })
			calculator.updateSettings({
				...config.options,
				invertedColors: jellyfish,
				keypad: expanded && editable,
				expressions: expanded && editable,
				settingsMenu: expanded,
				zoomButtons: true,
			})
			calculator.observe("change", () => setEditedState(calculator?.getState()))
		}).catch((cause) => { if (!disposed) setError(cause instanceof globalThis.Error ? cause.message : String(cause)) })
		return () => { disposed = true; calculator?.destroy(); calculatorRef.current = null }
	}, [config, desmosScriptUri, editable, expanded, jellyfish, themeId])

	useEffect(() => {
		calculatorRef.current?.updateSettings({
			invertedColors: jellyfish,
			keypad: expanded && editable,
			expressions: expanded && editable,
			settingsMenu: expanded,
			zoomButtons: true,
		})
		const timer = window.setTimeout(() => calculatorRef.current?.resize(), 0)
		return () => window.clearTimeout(timer)
	}, [expanded, editable, jellyfish])

	const resize = useCallback(() => calculatorRef.current?.resize(), [])
	useEffect(() => {
		if (typeof ResizeObserver === "undefined") return
		const observer = new ResizeObserver(resize)
		if (containerRef.current) observer.observe(containerRef.current)
		return () => observer.disconnect()
	}, [resize])

	const copy = (event: MouseEvent) => copyWithFeedback(`\`\`\`desmos\n${JSON.stringify(editedState || config, null, 2)}\n\`\`\``, event)
	const exportImage = () => {
		const data = calculatorRef.current?.screenshot({ width: 1200, height: expanded ? 800 : 500, targetPixelRatio: 2 })
		if (data) window.open(data, "_blank", "noopener,noreferrer")
	}

	return <Block>
		{config?.title && <Title>{config.title}</Title>}
		{error ? <ErrorMessage>{t("common:desmos.render_error") || "Failed to render function"}: {error}</ErrorMessage> : <Viewport $expanded={expanded} ref={containerRef} />}
		<Actions>
			{config?.display?.allowExpand !== false && <button onClick={() => setExpanded((value) => !value)}>{expanded ? t("common:desmos.collapse") : t("common:desmos.expand")}</button>}
			<button onClick={exportImage}>{t("common:desmos.export")}</button>
			<button onClick={copy}>{showCopyFeedback ? t("common:desmos.copied") : t("common:desmos.copy")}</button>
		</Actions>
	</Block>
}

const Block = styled.div`margin: 8px 0; border: 1px solid var(--vscode-widget-border); border-radius: 6px; overflow: hidden; background: var(--vscode-editor-background);`
const Title = styled.div`padding: 8px 12px; font-weight: 600; border-bottom: 1px solid var(--vscode-widget-border);`
const Viewport = styled.div<{ $expanded: boolean }>`height: ${({ $expanded }) => ($expanded ? "min(720px, 70vh)" : "320px")}; min-height: 220px; width: 100%;`
const Actions = styled.div`display: flex; gap: 6px; justify-content: flex-end; padding: 6px 8px; border-top: 1px solid var(--vscode-widget-border); button { color: var(--vscode-button-foreground); background: var(--vscode-button-background); border: 0; padding: 4px 8px; cursor: pointer; }`
const ErrorMessage = styled.div`padding: 16px; color: var(--vscode-errorForeground);`

import { memo, useMemo, useEffect, useState } from "react"
import { parseUnifiedDiff, type DiffLine } from "@src/utils/parseUnifiedDiff"
import { normalizeLanguage } from "@src/utils/highlighter"
import { getLanguageFromPath } from "@src/utils/getLanguageFromPath"
import { highlightHunks } from "@src/utils/highlightDiff"

interface DiffViewProps {
	source: string
	filePath?: string
}

// Interface for hunk data
interface Hunk {
	lines: DiffLine[]
	oldText: string
	newText: string
	highlightedOldLines?: React.ReactNode[]
	highlightedNewLines?: React.ReactNode[]
}

/**
 * DiffView component renders unified diffs with side-by-side line numbers
 * matching VSCode's diff editor style
 */
const DiffView = memo(({ source, filePath }: DiffViewProps) => {
	// Determine language from file path
	const normalizedLang = useMemo(() => normalizeLanguage(getLanguageFromPath(filePath || "") || "txt"), [filePath])

	const isLightTheme = useMemo(() => {
		if (typeof document === "undefined") return false
		const cls = document.body.className
		return /\bvscode-light\b|\bvscode-high-contrast-light\b/i.test(cls)
	}, [])

	// Disable syntax highlighting for large diffs (performance optimization)
	const shouldHighlight = useMemo(() => {
		const lineCount = source.split("\n").length
		return lineCount <= 1000 // Only highlight diffs with <= 1000 lines
	}, [source])

	// Parse diff and group into hunks
	const diffLines = useMemo(() => parseUnifiedDiff(source, filePath), [source, filePath])

	const hunks = useMemo(() => {
		const result: Hunk[] = []
		let currentHunk: DiffLine[] = []

		for (const line of diffLines) {
			if (line.type === "gap") {
				// Finish current hunk if it has content
				if (currentHunk.length > 0) {
					const oldLines: string[] = []
					const newLines: string[] = []

					for (const hunkLine of currentHunk) {
						if (hunkLine.type === "deletion" || hunkLine.type === "context") {
							oldLines.push(hunkLine.content)
						}
						if (hunkLine.type === "addition" || hunkLine.type === "context") {
							newLines.push(hunkLine.content)
						}
					}

					result.push({
						lines: [...currentHunk],
						oldText: oldLines.join("\n"),
						newText: newLines.join("\n"),
					})
				}

				// Start new hunk with the gap
				currentHunk = [line]
			} else {
				currentHunk.push(line)
			}
		}

		// Add the last hunk if it has content
		if (currentHunk.length > 0 && currentHunk.some((line) => line.type !== "gap")) {
			const oldLines: string[] = []
			const newLines: string[] = []

			for (const hunkLine of currentHunk) {
				if (hunkLine.type === "deletion" || hunkLine.type === "context") {
					oldLines.push(hunkLine.content)
				}
				if (hunkLine.type === "addition" || hunkLine.type === "context") {
					newLines.push(hunkLine.content)
				}
			}

			result.push({
				lines: [...currentHunk],
				oldText: oldLines.join("\n"),
				newText: newLines.join("\n"),
			})
		}

		return result
	}, [diffLines])

	// State for the processed hunks with highlighting
	const [processedHunks, setProcessedHunks] = useState<Hunk[]>(hunks)

	// Effect to handle async highlighting
	useEffect(() => {
		if (!shouldHighlight) {
			setProcessedHunks(hunks)
			return
		}

		const processHunks = async () => {
			const processed: Hunk[] = []

			for (let i = 0; i < hunks.length; i++) {
				const hunk = hunks[i]
				try {
					const highlighted = await highlightHunks(
						hunk.oldText,
						hunk.newText,
						normalizedLang,
						isLightTheme ? "light" : "dark",
						i,
						filePath,
					)
					processed.push({
						...hunk,
						highlightedOldLines: highlighted.oldLines,
						highlightedNewLines: highlighted.newLines,
					})
				} catch {
					// Fall back to unhighlighted on error
					processed.push(hunk)
				}
			}

			setProcessedHunks(processed)
		}

		processHunks()
	}, [hunks, shouldHighlight, normalizedLang, isLightTheme, filePath])

	// Render helper that uses precomputed highlighting
	const renderContent = (line: DiffLine, hunk: Hunk, lineIndexInHunk: number): React.ReactNode => {
		if (!shouldHighlight || !hunk.highlightedOldLines || !hunk.highlightedNewLines) {
			return line.content
		}

		// Find the line index within the old/new text for this hunk
		const hunkLinesBeforeThis = hunk.lines.slice(0, lineIndexInHunk).filter((l) => l.type !== "gap")

		if (line.type === "deletion") {
			// Count deletions and context lines before this line
			const oldLineIndex = hunkLinesBeforeThis.filter((l) => l.type === "deletion" || l.type === "context").length
			return hunk.highlightedOldLines[oldLineIndex] || line.content
		} else if (line.type === "addition") {
			// Count additions and context lines before this line
			const newLineIndex = hunkLinesBeforeThis.filter((l) => l.type === "addition" || l.type === "context").length
			return hunk.highlightedNewLines[newLineIndex] || line.content
		} else if (line.type === "context") {
			// For context lines, prefer new-side highlighting, fall back to old-side
			const newLineIndex = hunkLinesBeforeThis.filter((l) => l.type === "addition" || l.type === "context").length
			const oldLineIndex = hunkLinesBeforeThis.filter((l) => l.type === "deletion" || l.type === "context").length
			return hunk.highlightedNewLines[newLineIndex] || hunk.highlightedOldLines[oldLineIndex] || line.content
		}

		return line.content
	}

	return (
		<div className="diff-view bg-[var(--vscode-editor-background)] rounded-md overflow-hidden text-[0.95em]">
			<div className="overflow-x-hidden">
				<table className="w-full border-collapse table-auto">
					<tbody>
						{processedHunks.flatMap((hunk, hunkIndex) =>
							hunk.lines.map((line, lineIndex) => {
								const globalIndex = `${hunkIndex}-${lineIndex}`

								// Render compact separator between hunks
								if (line.type === "gap") {
									return (
										<tr key={globalIndex}>
											<td className="w-[45px] text-right pr-3 pl-2 select-none align-top whitespace-nowrap bg-[var(--vscode-editor-background)]" />
											<td className="w-[45px] text-right pr-3 select-none align-top whitespace-nowrap bg-[var(--vscode-editor-background)]" />
											<td className="w-[12px] align-top bg-[var(--vscode-editor-background)]" />
											{/* +/- column (empty for gap) */}
											<td className="w-[16px] text-center select-none bg-[var(--vscode-editor-background)]" />
											<td className="pr-3 whitespace-pre-wrap break-words w-full italic bg-[var(--vscode-editor-background)]">
												{`${line.hiddenCount ?? 0} hidden lines`}
											</td>
										</tr>
									)
								}

								// Use VSCode's built-in diff editor color variables as classes for gutters
								const gutterBgClass =
									line.type === "addition"
										? "bg-[var(--vscode-diffEditor-insertedTextBackground)]"
										: line.type === "deletion"
											? "bg-[var(--vscode-diffEditor-removedTextBackground)]"
											: "bg-[var(--vscode-editorGroup-border)]"

								const contentBgClass =
									line.type === "addition"
										? "diff-content-inserted"
										: line.type === "deletion"
											? "diff-content-removed"
											: "diff-content-context"

								const sign = line.type === "addition" ? "+" : line.type === "deletion" ? "-" : ""

								return (
									<tr key={globalIndex}>
										{/* Old line number */}
										<td
											className={`w-[45px] text-right pr-1 pl-1 select-none align-top whitespace-nowrap ${gutterBgClass}`}>
											{line.oldLineNum || ""}
										</td>
										{/* New line number */}
										<td
											className={`w-[45px] text-right pr-1 select-none align-top whitespace-nowrap ${gutterBgClass}`}>
											{line.newLineNum || ""}
										</td>
										{/* Narrow colored gutter */}
										<td className={`w-[12px] ${gutterBgClass} align-top`} />
										{/* +/- fixed column to prevent wrapping into it */}
										<td
											className={`w-[16px] text-center select-none whitespace-nowrap px-1 ${gutterBgClass}`}>
											{sign}
										</td>
										{/* Code content (no +/- prefix here) */}
										<td
											className={`pl-1 pr-3 whitespace-pre-wrap break-words w-full ${contentBgClass}`}>
											{renderContent(line, hunk, lineIndex)}
										</td>
									</tr>
								)
							}),
						)}
					</tbody>
				</table>
			</div>
		</div>
	)
})

export default DiffView

import { useCallback, forwardRef, useState, useEffect } from "react"
import { DecoratedVSCodeTextField, VSCodeTextFieldWithNodesProps } from "./DecoratedVSCodeTextField"

export interface InputFormatter<T> {
	/**
	 * Parse the raw input string into the typed value
	 */
	parse: (input: string) => T | undefined

	/**
	 * Format the typed value for display in the input field
	 */
	format: (value: T | undefined) => string

	/**
	 * Filter/transform the input as the user types (optional)
	 */
	filter?: (input: string) => string
}

interface FormattedTextFieldProps<T> extends Omit<VSCodeTextFieldWithNodesProps, "value" | "onInput"> {
	value: T | undefined
	onValueChange: (value: T | undefined) => void
	formatter: InputFormatter<T>
}

function FormattedTextFieldInner<T>(
	{ value, onValueChange, formatter, ...restProps }: FormattedTextFieldProps<T>,
	forwardedRef: React.Ref<HTMLInputElement>,
) {
	const [rawInput, setRawInput] = useState<string>("")
	const [isTyping, setIsTyping] = useState(false)

	// Update raw input when external value changes (but not when we're actively typing)
	useEffect(() => {
		if (!isTyping) {
			setRawInput(formatter.format(value))
		}
	}, [value, formatter, isTyping])

	const handleInput = useCallback(
		(e: React.FormEvent<HTMLInputElement>) => {
			const input = e.target as HTMLInputElement
			setIsTyping(true)

			let filteredValue = input.value
			if (formatter.filter) {
				filteredValue = formatter.filter(input.value)
				input.value = filteredValue
			}

			setRawInput(filteredValue)
			const parsedValue = formatter.parse(filteredValue)
			onValueChange(parsedValue)
		},
		[formatter, onValueChange],
	)

	const handleBlur = useCallback(() => {
		setIsTyping(false)
		// On blur, format the value properly
		setRawInput(formatter.format(value))
	}, [formatter, value])

	const displayValue = isTyping ? rawInput : formatter.format(value)

	return (
		<DecoratedVSCodeTextField
			{...restProps}
			value={displayValue}
			onInput={handleInput}
			onBlur={handleBlur}
			ref={forwardedRef}
		/>
	)
}

export const FormattedTextField = forwardRef(FormattedTextFieldInner as any) as <T>(
	props: FormattedTextFieldProps<T> & { ref?: React.Ref<HTMLInputElement> },
) => React.ReactElement

// Common formatters for reuse
export const unlimitedIntegerFormatter: InputFormatter<number> = {
	parse: (input: string) => {
		if (input.trim() === "") return undefined
		const value = parseInt(input)
		return !isNaN(value) && value > 0 ? value : undefined
	},
	format: (value: number | undefined) => {
		return value === undefined || value === Infinity ? "" : value.toString()
	},
	filter: (input: string) => input.replace(/[^0-9]/g, ""),
}

export const unlimitedDecimalFormatter: InputFormatter<number> = {
	parse: (input: string) => {
		if (input.trim() === "") return undefined
		const value = parseFloat(input)
		return !isNaN(value) && value >= 0 ? value : undefined
	},
	format: (value: number | undefined) => {
		return value === undefined || value === Infinity ? "" : value.toString()
	},
	filter: (input: string) => {
		// Remove all non-numeric and non-dot characters
		let cleanValue = input.replace(/[^0-9.]/g, "")

		// Handle multiple dots - keep only the first one
		const firstDotIndex = cleanValue.indexOf(".")
		if (firstDotIndex !== -1) {
			// Keep everything up to and including the first dot, then remove any additional dots
			const beforeDot = cleanValue.substring(0, firstDotIndex + 1)
			const afterDot = cleanValue.substring(firstDotIndex + 1).replace(/\./g, "")
			cleanValue = beforeDot + afterDot
		}

		return cleanValue
	},
}

