const MarkdownBlock = memo(({ markdown }: MarkdownBlockProps) => {
	const components = useMemo(
		() => ({
			table: ({ children, ...props }: any) => {
				return (
					<div className="table-wrapper">
						<table {...props}>{children}</table>
					</div>
				)
			},
			a: ({ href, children, ...props }: any) => {
				const handleClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
					// Only process file:// protocol or local file paths
					const isLocalPath = href?.startsWith("file://") || href?.startsWith("/") || !href?.includes("://")

					if (!isLocalPath) {
						return
					}

					e.preventDefault()

					// Handle absolute vs project-relative paths
					let filePath = href.replace("file://", "")

					// Extract line number if present
					const match = filePath.match(/(.*):(\d+)(-\d+)?$/)
					let values = undefined
					if (match) {
						filePath = match[1]
						values = { line: parseInt(match[2]) }
					}

					// Add ./ prefix if needed
					if (!filePath.startsWith("/") && !filePath.startsWith("./")) {
						filePath = "./" + filePath
					}

					vscode.postMessage({
						type: "openFile",
						text: filePath,
						values,
					})
				}

				return (
					<a {...props} href={href} onClick={handleClick}>
						{children}
					</a>
				)
			},
			pre: ({ children, ..._props }: any) => {
				// The structure from react-markdown v9 is: pre > code > text
				const codeEl = children as React.ReactElement

				if (!codeEl || !codeEl.props) {
					return <pre>{children}</pre>
				}

				const { className = "", children: codeChildren } = codeEl.props

				// Get the actual code text
				let codeString = ""
				if (typeof codeChildren === "string") {
					codeString = codeChildren
				} else if (Array.isArray(codeChildren)) {
					codeString = codeChildren.filter((child) => typeof child === "string").join("")
				}

				// Handle mermaid diagrams
				if (className.includes("language-mermaid")) {
					return (
						<div style={{ margin: "1em 0" }}>
							<MermaidBlock code={codeString} />
						</div>
					)
				}

				// Handle desmos function plots
				if (className.includes("language-desmos")) {
					return (
						<div style={{ margin: "1em 0" }}>
							<DesmosBlock code={codeString.trim()} />
						</div>
					)
				}

				// Extract language from className
				const match = /language-(\w+)/.exec(className)
				const language = match ? match[1] : "text"

				// Wrap CodeBlock in a div to ensure proper separation
				return (
					<div style={{ margin: "1em 0" }}>
						<CodeBlock source={codeString} language={language} />
					</div>
				)
			},
			code: ({ children, className, ...props }: any) => {
				// This handles inline code
				return (
					<code className={className} {...props}>
						{children}
					</code>
				)
			},
			blockquote: ({ children, className, "data-alert-type": alertType, ..._rest }: any) => {
				// The remarkGithubAlerts plugin tags alert blockquotes with a
				// `data-alert-type` attribute and `markdown-alert*` classes.
				// Anything without that attribute is a normal blockquote and
				// must render unchanged.
				const typedAlertType = alertType as AlertType | undefined

				if (!typedAlertType || !(typedAlertType in ALERT_ICONS)) {
					return <blockquote className={className}>{children}</blockquote>
				}

				return (
					<blockquote className={className} data-alert-type={typedAlertType}>
						<div className="markdown-alert-title">
							<span className={`codicon ${ALERT_ICONS[typedAlertType]}`} aria-hidden="true" />
							<span>{ALERT_LABELS[typedAlertType]}</span>
						</div>
						{children}
					</blockquote>
				)
			},
		}),
		[],
	)

	return (
		<StyledMarkdown>
			<ReactMarkdown
				remarkPlugins={[
					// singleTilde: false so a single "~" around text (e.g. "1~3", "~10") is not
					// rendered as strikethrough; only "~~text~~" is. Matches VS Code's markdown. (#154)
					[remarkGfm, { singleTilde: false }],
					remarkMath,
					remarkGithubAlerts,
					() => {
						return (tree: any) => {
							visit(tree, "code", (node: any) => {
								if (!node.lang) {
									node.lang = "text"
								} else if (node.lang.includes(".")) {
									node.lang = node.lang.split(".").slice(-1)[0]
								}
							})
						}
					},
				]}
				rehypePlugins={[rehypeKatex as any]}
				components={components}>
				{repairMalformedDesmosBlocks(markdown || "")}
			</ReactMarkdown>
		</StyledMarkdown>
	)
})

export default MarkdownBlock

import React, { HTMLAttributes, useCallback, forwardRef, useRef } from "react"

import { useExtensionState } from "@/context/ExtensionStateContext"
import { cn } from "@/lib/utils"

type TabProps = HTMLAttributes<HTMLDivElement>

export const Tab = ({ className, children, ...props }: TabProps) => (
	<div className={cn("fixed inset-0 flex flex-col", className)} {...props}>
		{children}
	</div>
)

export const TabHeader = ({ className, children, ...props }: TabProps) => (
	<div className={cn("px-5 py-2.5 border-b border-vscode-panel-border", className)} {...props}>
		{children}
	</div>
)

export const TabContent = forwardRef<HTMLDivElement, TabProps>(({ className, children, ...props }, ref) => {
	const { renderContext } = useExtensionState()

	const onWheel = useCallback(
		(e: React.WheelEvent<HTMLDivElement>) => {
			if (renderContext !== "editor") {
				return
			}

			const target = e.target as HTMLElement

			// Prevent scrolling if the target is a listbox or option
			// (e.g. selects, dropdowns, etc).
			if (target.role === "listbox" || target.role === "option") {
				return
			}

			e.currentTarget.scrollTop += e.deltaY
		},
		[renderContext],
	)

	return (
		<div ref={ref} className={cn("flex-1 overflow-auto p-5", className)} onWheel={onWheel} {...props}>
			{children}
		</div>
	)
})
TabContent.displayName = "TabContent"

export const TabList = forwardRef<
	HTMLDivElement,
	HTMLAttributes<HTMLDivElement> & {
		value: string
		onValueChange: (value: string) => void
	}
>(({ children, className, value, onValueChange, ...props }, ref) => {
	const tabRefs = useRef<Array<HTMLButtonElement | null>>([])
	const tabs = React.Children.toArray(children).filter(React.isValidElement)

	const focusTab = (index: number) => {
		const nextIndex = (index + tabs.length) % tabs.length
		const tab = tabRefs.current[nextIndex]
		if (!tab) return
		tab.focus()
		const nextValue = (tabs[nextIndex] as React.ReactElement<{ value: string }>).props.value
		onValueChange(nextValue)
	}

	return (
		<div ref={ref} role="tablist" className={cn("flex", className)} {...props}>
			{tabs.map((child, index) => {
				const tab = child as React.ReactElement<any>
				const tabId = `tab-${String(tab.props.value).replace(/[^a-zA-Z0-9_-]/g, "-")}`
				const panelId = `${tabId}-panel`
				return React.cloneElement(tab, {
					id: tab.props.id ?? tabId,
					"aria-controls": tab.props["aria-controls"] ?? panelId,
					ref: (element: HTMLButtonElement | null) => {
						tabRefs.current[index] = element
					},
					isSelected: tab.props.value === value,
					onSelect: () => onValueChange(tab.props.value),
					onKeyDown: (event: React.KeyboardEvent<HTMLButtonElement>) => {
						if (event.key === "ArrowRight" || event.key === "ArrowDown") {
							event.preventDefault()
							focusTab(index + 1)
						} else if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
							event.preventDefault()
							focusTab(index - 1)
						} else if (event.key === "Home") {
							event.preventDefault()
							focusTab(0)
						} else if (event.key === "End") {
							event.preventDefault()
							focusTab(tabs.length - 1)
						}
						tab.props.onKeyDown?.(event)
					},
				})
			})}
		</div>
	)
})

export const TabTrigger = forwardRef<
	HTMLButtonElement,
	React.ButtonHTMLAttributes<HTMLButtonElement> & {
		value: string
		isSelected?: boolean
		onSelect?: () => void
	}
>(({ children, className, value: _value, isSelected, onSelect, ...props }, ref) => {
	return (
		<button
			ref={ref}
		role="tab"
			aria-selected={isSelected}
			aria-controls={props["aria-controls"]}
			tabIndex={isSelected ? 0 : -1}
			className={cn("focus:outline-none focus:ring-2 focus:ring-vscode-focusBorder", className)}
			onClick={onSelect}
			{...props}>
			{children}
		</button>
	)
})

