export const ExtensionStateContext = createContext<ExtensionStateContextType | undefined>(undefined)

export const mergeExtensionState = (prevState: ExtensionState, newState: Partial<ExtensionState>) => {
	const { customModePrompts: prevCustomModePrompts, experiments: prevExperiments, ...prevRest } = prevState

	const {
		apiConfiguration,
		customModePrompts: newCustomModePrompts,
		customSupportPrompts,
		experiments: newExperiments,
		...newRest
	} = newState

	const customModePrompts = { ...prevCustomModePrompts, ...(newCustomModePrompts ?? {}) }
	const experiments = { ...prevExperiments, ...(newExperiments ?? {}) }
	const rest = { ...prevRest, ...newRest }
	const hasCurrentTaskIdUpdate = Object.prototype.hasOwnProperty.call(newState, "currentTaskId")
	const didTaskChange =
		hasCurrentTaskIdUpdate && newState.currentTaskId !== prevState.currentTaskId
	const prevMessages = prevState.clineMessages ?? []
	const incomingMessages = newState.clineMessages
	const isIncomingMessageListEmpty = incomingMessages !== undefined && incomingMessages.length === 0
	const prevLastMessageTs = prevMessages.at(-1)?.ts ?? 0
	const incomingLastMessageTs = incomingMessages?.at(-1)?.ts ?? 0
	const hasIncomingOlderMessages =
		!isIncomingMessageListEmpty &&
		!didTaskChange &&
		incomingMessages !== undefined &&
		(incomingMessages.length < prevMessages.length || incomingLastMessageTs < prevLastMessageTs)

	// Protect chat-derived state from stale state pushes using sequence numbering.
	// Multiple async event sources (cloud auth, settings, task streaming) can trigger
	// concurrent state pushes. If a stale push arrives after a newer one, its clineMessages
	// would overwrite the newer messages. The sequence number prevents this by only applying
	// clineMessages when the incoming seq is strictly greater than the last applied seq.
	//
	// OrchestratorSession is derived from the current Task snapshot in the same state payloads.
	// If we allow a stale payload to overwrite it, the stage highlight can jump backward
	// (for example, Worker/Reviewer reverting to Planner). Keep it in sync with the same
	// stale-payload guard used for clineMessages.
	//
	// We also compare message timestamps/length because state sequence numbers are assigned
	// when a payload is sent, not when its snapshot was captured. A slow older snapshot can
	// therefore arrive later with a higher seq and still be stale.
	if (
		newState.clineMessages !== undefined &&
		((newState.clineMessagesSeq !== undefined &&
			prevState.clineMessagesSeq !== undefined &&
			newState.clineMessagesSeq <= prevState.clineMessagesSeq) ||
			hasIncomingOlderMessages)
	) {
		rest.clineMessages = prevState.clineMessages
		rest.clineMessagesSeq = prevState.clineMessagesSeq
	}

	// Note that we completely replace the previous apiConfiguration and customSupportPrompts objects
	// with new ones since the state that is broadcast is the entire objects so merging is not necessary.
	return {
		...rest,
		apiConfiguration: apiConfiguration ?? prevState.apiConfiguration,
		customModePrompts,
		customSupportPrompts: customSupportPrompts ?? prevState.customSupportPrompts,
		experiments,
	}
}

export const ExtensionStateContextProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
	const [state, setState] = useState<ExtensionState>({
		apiConfiguration: {},
		version: "",
		clineMessages: [],
		desmosScriptUri: undefined,
		builtinProtocolCapabilities: {
			desmos: {
				enabled: true,
				trigger: "fenced_code_block",
				language: "desmos",
			},
		},
		taskHistory: [],
		shouldShowAnnouncement: false,
		allowedCommands: [],
		deniedCommands: [],
		soundEnabled: false,
		soundVolume: 0.5,
		ttsEnabled: false,
		ttsSpeed: 1.0,
		enableCheckpoints: true,
		checkpointTimeout: DEFAULT_CHECKPOINT_TIMEOUT_SECONDS, // Default to 15 seconds
		language: "en", // Default language code
		writeDelayMs: 1000,
		terminalShellIntegrationTimeout: 4000,
		mcpEnabled: true,
		taskSyncEnabled: false,
		currentApiConfigName: "default",
		listApiConfigMeta: [],
		mode: defaultModeSlug,
		customModePrompts: defaultPrompts,
		customSupportPrompts: {},
		experiments: experimentDefault,
		enhancementApiConfigId: "",
		hasOpenedModeSelector: false, // Default to false (not opened yet)
		autoApprovalEnabled: false,
		customModes: [],
		maxOpenTabsContext: 20,
		maxWorkspaceFiles: 200,
		cwd: "",
		telemetrySetting: "unset",
		showRooIgnoredFiles: true, // Default to showing .rooignore'd files with lock symbol (current behavior).
		enableSubfolderRules: false, // Default to disabled - must be enabled to load rules from subdirectories
		renderContext: "sidebar",
		maxReadFileLine: -1, // Default max line limit for read_file tool (-1 for default)
		maxImageFileSize: 5, // Default max image file size in MB
		maxTotalImageSize: 20, // Default max total image size in MB
		pinnedApiConfigs: {}, // Empty object for pinned API configs
		terminalZshOhMy: false, // Default Oh My Zsh integration setting
		terminalZshP10k: false, // Default Powerlevel10k integration setting
		terminalZdotdir: false, // Default ZDOTDIR handling setting
		terminalProfile: undefined, // Default VS Code terminal profile (use VS Code default)
		historyPreviewCollapsed: false, // Initialize the new state (default to expanded)
		reasoningBlockCollapsed: true, // Default to collapsed
		enterBehavior: "send", // Default: Enter sends, Shift+Enter creates newline
		cloudUserInfo: null,
		cloudIsAuthenticated: false,
		cloudOrganizations: [],
		sharingEnabled: false,
		publicSharingEnabled: false,
		organizationAllowList: ORGANIZATION_ALLOW_ALL,
		organizationSettingsVersion: -1,
		autoCondenseContext: true,
		autoCondenseContextPercent: 100,
		profileThresholds: {},
		codebaseIndexConfig: {
			codebaseIndexEnabled: true,
			codebaseIndexQdrantUrl: "http://localhost:6333",
			codebaseIndexEmbedderProvider: "openai",
			codebaseIndexEmbedderBaseUrl: "",
			codebaseIndexEmbedderModelId: "",
			codebaseIndexSearchMaxResults: undefined,
			codebaseIndexSearchMinScore: undefined,
		},
		codebaseIndexModels: { ollama: {}, openai: {} },
		includeDiagnosticMessages: true,
		maxDiagnosticMessages: 50,
		openRouterImageApiKey: "",
		openRouterImageGenerationSelectedModel: "",
		includeCurrentTime: true,
		includeCurrentCost: true,
		lockApiConfigAcrossModes: false,
	})

	const [didHydrateState, setDidHydrateState] = useState(false)
	const [showWelcome, setShowWelcome] = useState(false)
	const [theme, setTheme] = useState<any>(undefined)
	const [filePaths, setFilePaths] = useState<string[]>([])
	const [openedTabs, setOpenedTabs] = useState<Array<{ label: string; isActive: boolean; path?: string }>>([])
	const [commands, setCommands] = useState<Command[]>([])
	const [mcpServers, setMcpServers] = useState<McpServer[]>([])
	const [currentCheckpoint, setCurrentCheckpoint] = useState<string>()
	const [extensionRouterModels, setExtensionRouterModels] = useState<RouterModels | undefined>(undefined)
	const [marketplaceItems, setMarketplaceItems] = useState<any[]>([])
	const [marketplaceInstalledMetadata, setMarketplaceInstalledMetadata] = useState<MarketplaceInstalledMetadata>({
		project: {},
		global: {},
	})
	const [alwaysAllowFollowupQuestions, setAlwaysAllowFollowupQuestions] = useState(false) // Add state for follow-up questions auto-approve
	const [followupAutoApproveTimeoutMs, setFollowupAutoApproveTimeoutMs] = useState<number | undefined>(undefined) // Will be set from global settings
	const [skills, setSkills] = useState<SkillMetadata[]>([])
	const [includeTaskHistoryInEnhance, setIncludeTaskHistoryInEnhance] = useState(true)
	const [includeCurrentTime, setIncludeCurrentTime] = useState(true)
	const [includeCurrentCost, setIncludeCurrentCost] = useState(true)

	const setListApiConfigMeta = useCallback(
		(value: ProviderSettingsEntry[]) => setState((prevState) => ({ ...prevState, listApiConfigMeta: value })),
		[],
	)

	const setApiConfiguration = useCallback((value: ProviderSettings) => {
		setState((prevState) => ({
			...prevState,
			apiConfiguration: {
				...prevState.apiConfiguration,
				...value,
			},
		}))
	}, [])

	const handleMessage = useCallback(
		(event: MessageEvent) => {
			const message: ExtensionMessage = event.data
			switch (message.type) {
				case "state": {
						const newState = message.state ?? {}
						setState((prevState) => mergeExtensionState(prevState, newState))
						setShowWelcome(!checkExistKey(newState.apiConfiguration))
						setDidHydrateState(true)
						// Handle marketplace data if present in state message
						if (newState.marketplaceItems !== undefined) {
							setMarketplaceItems(newState.marketplaceItems)
						}
						if (newState.marketplaceInstalledMetadata !== undefined) {
							setMarketplaceInstalledMetadata(newState.marketplaceInstalledMetadata)
						}
					// Update alwaysAllowFollowupQuestions if present in state message
					if ((newState as any).alwaysAllowFollowupQuestions !== undefined) {
						setAlwaysAllowFollowupQuestions((newState as any).alwaysAllowFollowupQuestions)
					}
					// Update followupAutoApproveTimeoutMs if present in state message
					if ((newState as any).followupAutoApproveTimeoutMs !== undefined) {
						setFollowupAutoApproveTimeoutMs((newState as any).followupAutoApproveTimeoutMs)
					}
					// Update includeTaskHistoryInEnhance if present in state message
					if ((newState as any).includeTaskHistoryInEnhance !== undefined) {
						setIncludeTaskHistoryInEnhance((newState as any).includeTaskHistoryInEnhance)
					}
					// Update includeCurrentTime if present in state message
					if ((newState as any).includeCurrentTime !== undefined) {
						setIncludeCurrentTime((newState as any).includeCurrentTime)
					}
					// Update includeCurrentCost if present in state message
					if ((newState as any).includeCurrentCost !== undefined) {
						setIncludeCurrentCost((newState as any).includeCurrentCost)
					}
					break
				}
				case "action": {
					if (message.action === "toggleAutoApprove") {
						// Toggle the auto-approval state
						setState((prevState) => {
							const newValue = !(prevState.autoApprovalEnabled ?? false)
							// Also send the update to the extension
							vscode.postMessage({ type: "autoApprovalEnabled", bool: newValue })
							return { ...prevState, autoApprovalEnabled: newValue }
						})
					}
					break
				}
				case "theme": {
					if (message.text) {
						setTheme(convertTextMateToHljs(JSON.parse(message.text)))
					}
					break
				}
				case "workspaceUpdated": {
					const paths = message.filePaths ?? []
					const tabs = message.openedTabs ?? []

					setFilePaths(paths)
					setOpenedTabs(tabs)
					break
				}
				case "commands": {
					setCommands(message.commands ?? [])
					break
				}
				case "messageUpdated": {
					const clineMessage = message.clineMessage!
					setState((prevState) => {
						// worth noting it will never be possible for a more up-to-date message to be sent here or in normal messages post since the presentAssistantContent function uses lock
						const lastIndex = findLastIndex(prevState.clineMessages, (msg) => msg.ts === clineMessage.ts)
						if (lastIndex !== -1) {
							const newClineMessages = [...prevState.clineMessages]
							newClineMessages[lastIndex] = clineMessage
							return { ...prevState, clineMessages: newClineMessages }
						}
						// If the matching message has not been inserted yet, fall back to
						// inserting the update as a new message so the UI still reflects the
						// user's action. This covers orchestrator-start messages, which can arrive
						// before the first clineMessages snapshot is present in the webview.
						const insertIndex = findLastIndex(prevState.clineMessages, (msg) => msg.ts <= clineMessage.ts) + 1
						const newClineMessages = [...prevState.clineMessages]
						newClineMessages.splice(insertIndex, 0, clineMessage)
						console.warn(
							`[messageUpdated] Received update for unknown message ts=${clineMessage.ts}; inserting fallback entry. ` +
								`Frontend had ${prevState.clineMessages.length} messages.`,
						)
						return { ...prevState, clineMessages: newClineMessages }
					})
					break
				}
				case "skills": {
					if (message.skills) {
						setSkills(message.skills)
					}
					break
				}
				case "mcpServers": {
					setMcpServers(message.mcpServers ?? [])
					break
				}
				case "currentCheckpointUpdated": {
					setCurrentCheckpoint(message.text)
					break
				}
				case "listApiConfig": {
					setListApiConfigMeta(message.listApiConfig ?? [])
					break
				}
				case "routerModels": {
						setExtensionRouterModels(message.routerModels)
						break
					}
					case "marketplaceData": {
						if (message.marketplaceItems !== undefined) {
							setMarketplaceItems(message.marketplaceItems)
						}
						if (message.marketplaceInstalledMetadata !== undefined) {
							setMarketplaceInstalledMetadata(message.marketplaceInstalledMetadata)
						}
						break
					}
				case "taskHistoryUpdated": {
					// Efficiently update just the task history without replacing entire state
					if (message.taskHistory !== undefined) {
						setState((prevState) => ({
							...prevState,
							taskHistory: message.taskHistory!,
						}))
					}
					break
				}
				case "taskHistoryItemUpdated": {
					const item = message.taskHistoryItem
					if (!item) {
						break
					}
					setState((prevState) => {
						const existingIndex = prevState.taskHistory.findIndex((h) => h.id === item.id)
						let nextHistory: typeof prevState.taskHistory
						if (existingIndex === -1) {
							nextHistory = [item, ...prevState.taskHistory]
						} else {
							nextHistory = [...prevState.taskHistory]
							nextHistory[existingIndex] = item
						}
						// Keep UI semantics consistent with extension: newest-first ordering.
						nextHistory.sort((a, b) => b.ts - a.ts)
						return {
							...prevState,
							taskHistory: nextHistory,
							currentTaskItem:
								prevState.currentTaskItem?.id === item.id ? item : prevState.currentTaskItem,
						}
					})
					break
				}
				// orchestratorChatMessage removed: orchestrator messages are now written directly
				// to clineMessages via task.sayWithOrchestratorMeta(), so they appear naturally
				// in the chat without needing a separate insertion mechanism.
				// orchestratorSessionUpdate and orchestratorCostUpdate removed:
				// Orchestrator state is now derived from the current Task's orchestratorState
				// and pushed via the regular state message (see getStateToPostToWebview).
			}
		},
		[setListApiConfigMeta],
	)

	useEffect(() => {
		window.addEventListener("message", handleMessage)
		return () => {
			window.removeEventListener("message", handleMessage)
		}
	}, [handleMessage])

	useEffect(() => {
		vscode.postMessage({ type: "webviewDidLaunch" })
	}, [])

	// Apply the configurable chat font size as a CSS variable. When unset, the
	// override is removed so the UI falls back to VS Code's `--vscode-font-size`.
	useEffect(() => {
		const root = document.documentElement
		if (typeof state.chatFontSize === "number") {
			root.style.setProperty("--vertex-chat-font-size", `${state.chatFontSize}px`)
		} else {
			root.style.removeProperty("--vertex-chat-font-size")
		}
	}, [state.chatFontSize])

	const contextValue: ExtensionStateContextType = {
		...state,
		// `chatFontSize` is persisted as nullish (null on reset); normalize null to
		// undefined so it matches the context type and means "use VS Code default".
		chatFontSize: state.chatFontSize ?? undefined,
		reasoningBlockCollapsed: state.reasoningBlockCollapsed ?? true,
		didHydrateState,
		showWelcome,
		theme,
		mcpServers,
		currentCheckpoint,
		filePaths,
		openedTabs,
		commands,
		soundVolume: state.soundVolume,
		ttsSpeed: state.ttsSpeed,
		writeDelayMs: state.writeDelayMs,
		routerModels: extensionRouterModels,
		cloudIsAuthenticated: state.cloudIsAuthenticated ?? false,
		cloudOrganizations: state.cloudOrganizations ?? [],
		organizationSettingsVersion: state.organizationSettingsVersion ?? -1,
		marketplaceItems,
		marketplaceInstalledMetadata,
		profileThresholds: state.profileThresholds ?? {},
		alwaysAllowFollowupQuestions,
		followupAutoApproveTimeoutMs,
		taskSyncEnabled: state.taskSyncEnabled,
		setExperimentEnabled: (id, enabled) =>
			setState((prevState) => ({ ...prevState, experiments: { ...prevState.experiments, [id]: enabled } })),
		setApiConfiguration,
		setCustomInstructions: (value) => setState((prevState) => ({ ...prevState, customInstructions: value })),
		setAlwaysAllowReadOnly: (value) => setState((prevState) => ({ ...prevState, alwaysAllowReadOnly: value })),
		setAlwaysAllowReadOnlyOutsideWorkspace: (value) =>
			setState((prevState) => ({ ...prevState, alwaysAllowReadOnlyOutsideWorkspace: value })),
		setAlwaysAllowWrite: (value) => setState((prevState) => ({ ...prevState, alwaysAllowWrite: value })),
		setAlwaysAllowWriteOutsideWorkspace: (value) =>
			setState((prevState) => ({ ...prevState, alwaysAllowWriteOutsideWorkspace: value })),
		setAlwaysAllowExecute: (value) => setState((prevState) => ({ ...prevState, alwaysAllowExecute: value })),
		setAlwaysAllowMcp: (value) => setState((prevState) => ({ ...prevState, alwaysAllowMcp: value })),
		setAlwaysAllowModeSwitch: (value) => setState((prevState) => ({ ...prevState, alwaysAllowModeSwitch: value })),
		setAlwaysAllowSubtasks: (value) => setState((prevState) => ({ ...prevState, alwaysAllowSubtasks: value })),
		setAlwaysAllowFollowupQuestions,
		setFollowupAutoApproveTimeoutMs: (value) =>
			setState((prevState) => ({ ...prevState, followupAutoApproveTimeoutMs: value })),
		setShowAnnouncement: (value) => setState((prevState) => ({ ...prevState, shouldShowAnnouncement: value })),
		setAllowedCommands: (value) => setState((prevState) => ({ ...prevState, allowedCommands: value })),
		setDeniedCommands: (value) => setState((prevState) => ({ ...prevState, deniedCommands: value })),
		setAllowedMaxRequests: (value) => setState((prevState) => ({ ...prevState, allowedMaxRequests: value })),
		setAllowedMaxCost: (value) => setState((prevState) => ({ ...prevState, allowedMaxCost: value })),
		setSoundEnabled: (value) => setState((prevState) => ({ ...prevState, soundEnabled: value })),
		setSoundVolume: (value) => setState((prevState) => ({ ...prevState, soundVolume: value })),
		setTtsEnabled: (value) => setState((prevState) => ({ ...prevState, ttsEnabled: value })),
		setTtsSpeed: (value) => setState((prevState) => ({ ...prevState, ttsSpeed: value })),
		setEnableCheckpoints: (value) => setState((prevState) => ({ ...prevState, enableCheckpoints: value })),
		setCheckpointTimeout: (value) => setState((prevState) => ({ ...prevState, checkpointTimeout: value })),
		setWriteDelayMs: (value) => setState((prevState) => ({ ...prevState, writeDelayMs: value })),
		setTerminalOutputPreviewSize: (value) =>
			setState((prevState) => ({ ...prevState, terminalOutputPreviewSize: value })),
		setTerminalShellIntegrationTimeout: (value) =>
			setState((prevState) => ({ ...prevState, terminalShellIntegrationTimeout: value })),
		setTerminalShellIntegrationDisabled: (value) =>
			setState((prevState) => ({ ...prevState, terminalShellIntegrationDisabled: value })),
		setTerminalZdotdir: (value) => setState((prevState) => ({ ...prevState, terminalZdotdir: value })),
		setMcpEnabled: (value) => setState((prevState) => ({ ...prevState, mcpEnabled: value })),
		setTaskSyncEnabled: (value) => setState((prevState) => ({ ...prevState, taskSyncEnabled: value }) as any),
		setCurrentApiConfigName: (value) => setState((prevState) => ({ ...prevState, currentApiConfigName: value })),
		setListApiConfigMeta,
		setMode: (value: Mode) => setState((prevState) => ({ ...prevState, mode: value })),
		setCustomModePrompts: (value) => setState((prevState) => ({ ...prevState, customModePrompts: value })),
		setCustomSupportPrompts: (value) => setState((prevState) => ({ ...prevState, customSupportPrompts: value })),
		setEnhancementApiConfigId: (value) =>
			setState((prevState) => ({ ...prevState, enhancementApiConfigId: value })),
		setAutoApprovalEnabled: (value) => setState((prevState) => ({ ...prevState, autoApprovalEnabled: value })),
		setCustomModes: (value) => setState((prevState) => ({ ...prevState, customModes: value })),
		setMaxOpenTabsContext: (value) => setState((prevState) => ({ ...prevState, maxOpenTabsContext: value })),
		setMaxWorkspaceFiles: (value) => setState((prevState) => ({ ...prevState, maxWorkspaceFiles: value })),
		setTelemetrySetting: (value) => setState((prevState) => ({ ...prevState, telemetrySetting: value })),
		setShowRooIgnoredFiles: (value) => setState((prevState) => ({ ...prevState, showRooIgnoredFiles: value })),
		setEnableSubfolderRules: (value) => setState((prevState) => ({ ...prevState, enableSubfolderRules: value })),
		setAwsUsePromptCache: (value) => setState((prevState) => ({ ...prevState, awsUsePromptCache: value })),
		setMaxImageFileSize: (value) => setState((prevState) => ({ ...prevState, maxImageFileSize: value })),
		setMaxTotalImageSize: (value) => setState((prevState) => ({ ...prevState, maxTotalImageSize: value })),
		setPinnedApiConfigs: (value) => setState((prevState) => ({ ...prevState, pinnedApiConfigs: value })),
		togglePinnedApiConfig: (configId) =>
			setState((prevState) => {
				const currentPinned = prevState.pinnedApiConfigs || {}
				const newPinned = {
					...currentPinned,
					[configId]: !currentPinned[configId],
				}

				// If the config is now unpinned, remove it from the object
				if (!newPinned[configId]) {
					delete newPinned[configId]
				}

				return { ...prevState, pinnedApiConfigs: newPinned }
			}),
		setHistoryPreviewCollapsed: (value) =>
			setState((prevState) => ({ ...prevState, historyPreviewCollapsed: value })),
		setReasoningBlockCollapsed: (value) =>
			setState((prevState) => ({ ...prevState, reasoningBlockCollapsed: value })),
		setChatFontSize: (value) => setState((prevState) => ({ ...prevState, chatFontSize: value })),
		enterBehavior: state.enterBehavior ?? "send",
		setEnterBehavior: (value) => setState((prevState) => ({ ...prevState, enterBehavior: value })),
		setHasOpenedModeSelector: (value) => setState((prevState) => ({ ...prevState, hasOpenedModeSelector: value })),
		setAutoCondenseContext: (value) => setState((prevState) => ({ ...prevState, autoCondenseContext: value })),
		setAutoCondenseContextPercent: (value) =>
			setState((prevState) => ({ ...prevState, autoCondenseContextPercent: value })),
		setProfileThresholds: (value) => setState((prevState) => ({ ...prevState, profileThresholds: value })),
		includeDiagnosticMessages: state.includeDiagnosticMessages,
		setIncludeDiagnosticMessages: (value) => {
			setState((prevState) => ({ ...prevState, includeDiagnosticMessages: value }))
		},
		maxDiagnosticMessages: state.maxDiagnosticMessages,
		setMaxDiagnosticMessages: (value) => {
			setState((prevState) => ({ ...prevState, maxDiagnosticMessages: value }))
		},
		includeTaskHistoryInEnhance,
		setIncludeTaskHistoryInEnhance,
		includeCurrentTime,
		setIncludeCurrentTime,
		includeCurrentCost,
		setIncludeCurrentCost,
		skills,
		showWorktreesInHomeScreen: state.showWorktreesInHomeScreen ?? true,
		setShowWorktreesInHomeScreen: (value) =>
			setState((prevState) => ({ ...prevState, showWorktreesInHomeScreen: value })),
	}

	return <ExtensionStateContext.Provider value={contextValue}>{children}</ExtensionStateContext.Provider>
}

export const useExtensionState = () => {
	const context = useContext(ExtensionStateContext)

	if (context === undefined) {
		throw new Error("useExtensionState must be used within an ExtensionStateContextProvider")
	}

	return context
}

import { renderHook } from "@testing-library/react"
import { useAutoApprovalState } from "../useAutoApprovalState"

describe("useAutoApprovalState", () => {
	describe("hasEnabledOptions", () => {
		it("should return false when all toggles are false", () => {
			const toggles = {
				alwaysAllowReadOnly: false,
				alwaysAllowWrite: false,
				alwaysAllowExecute: false,
				alwaysAllowMcp: false,
				alwaysAllowModeSwitch: false,
				alwaysAllowSubtasks: false,
				alwaysAllowFollowupQuestions: false,
			}

			const { result } = renderHook(() => useAutoApprovalState(toggles, true))

			expect(result.current.hasEnabledOptions).toBe(false)
		})

		it("should return false when all toggles are undefined", () => {
			const toggles = {
				alwaysAllowReadOnly: undefined,
				alwaysAllowWrite: undefined,
				alwaysAllowExecute: undefined,
				alwaysAllowMcp: undefined,
				alwaysAllowModeSwitch: undefined,
				alwaysAllowSubtasks: undefined,
				alwaysAllowFollowupQuestions: undefined,
			}

			const { result } = renderHook(() => useAutoApprovalState(toggles, true))

			expect(result.current.hasEnabledOptions).toBe(false)
		})

		it("should return true when at least one toggle is true", () => {
			const toggles = {
				alwaysAllowReadOnly: true,
				alwaysAllowWrite: false,
				alwaysAllowExecute: false,
				alwaysAllowMcp: false,
				alwaysAllowModeSwitch: false,
				alwaysAllowSubtasks: false,
				alwaysAllowFollowupQuestions: false,
			}

			const { result } = renderHook(() => useAutoApprovalState(toggles, true))

			expect(result.current.hasEnabledOptions).toBe(true)
		})

		it("should return true when multiple toggles are true", () => {
			const toggles = {
				alwaysAllowReadOnly: true,
				alwaysAllowWrite: true,
				alwaysAllowExecute: true,
				alwaysAllowMcp: false,
				alwaysAllowModeSwitch: false,
				alwaysAllowSubtasks: false,
				alwaysAllowFollowupQuestions: false,
			}

			const { result } = renderHook(() => useAutoApprovalState(toggles, true))

			expect(result.current.hasEnabledOptions).toBe(true)
		})

		it("should return true when all toggles are true", () => {
			const toggles = {
				alwaysAllowReadOnly: true,
				alwaysAllowWrite: true,
				alwaysAllowExecute: true,
				alwaysAllowMcp: true,
				alwaysAllowModeSwitch: true,
				alwaysAllowSubtasks: true,
				alwaysAllowFollowupQuestions: true,
			}

			const { result } = renderHook(() => useAutoApprovalState(toggles, true))

			expect(result.current.hasEnabledOptions).toBe(true)
		})
	})

	describe("effectiveAutoApprovalEnabled", () => {
		it("should return false when autoApprovalEnabled is false regardless of toggles", () => {
			const toggles = {
				alwaysAllowReadOnly: true,
				alwaysAllowWrite: true,
				alwaysAllowExecute: true,
			}

			const { result } = renderHook(() => useAutoApprovalState(toggles, false))

			expect(result.current.effectiveAutoApprovalEnabled).toBe(false)
		})

		it("should return false when autoApprovalEnabled is undefined regardless of toggles", () => {
			const toggles = {
				alwaysAllowReadOnly: true,
				alwaysAllowWrite: true,
				alwaysAllowExecute: true,
			}

			const { result } = renderHook(() => useAutoApprovalState(toggles, undefined))

			expect(result.current.effectiveAutoApprovalEnabled).toBe(false)
		})

		it("should return true when autoApprovalEnabled is true but no toggles are enabled", () => {
			const toggles = {
				alwaysAllowReadOnly: false,
				alwaysAllowWrite: false,
				alwaysAllowExecute: false,
				alwaysAllowMcp: false,
				alwaysAllowModeSwitch: false,
				alwaysAllowSubtasks: false,
				alwaysAllowFollowupQuestions: false,
			}

			const { result } = renderHook(() => useAutoApprovalState(toggles, true))

			expect(result.current.effectiveAutoApprovalEnabled).toBe(true)
		})

		it("should return true when autoApprovalEnabled is true and at least one toggle is enabled", () => {
			const toggles = {
				alwaysAllowReadOnly: true,
				alwaysAllowWrite: false,
				alwaysAllowExecute: false,
			}

			const { result } = renderHook(() => useAutoApprovalState(toggles, true))

			expect(result.current.effectiveAutoApprovalEnabled).toBe(true)
		})
	})

	describe("memoization", () => {
		it("should not recompute hasEnabledOptions when toggles object reference changes but values are the same", () => {
			const initialToggles = {
				alwaysAllowReadOnly: true,
				alwaysAllowWrite: false,
			}

			const { result, rerender } = renderHook(
				({ toggles, autoApprovalEnabled }) => useAutoApprovalState(toggles, autoApprovalEnabled),
				{
					initialProps: {
						toggles: initialToggles,
						autoApprovalEnabled: true,
					},
				},
			)

			const firstHasEnabledOptions = result.current.hasEnabledOptions
			const firstEffectiveAutoApprovalEnabled = result.current.effectiveAutoApprovalEnabled

			// Create new object with same values
			const newToggles = {
				alwaysAllowReadOnly: true,
				alwaysAllowWrite: false,
			}

			rerender({ toggles: newToggles, autoApprovalEnabled: true })

			// The computed values should be the same due to memoization
			expect(result.current.hasEnabledOptions).toBe(firstHasEnabledOptions)
			expect(result.current.effectiveAutoApprovalEnabled).toBe(firstEffectiveAutoApprovalEnabled)
		})

		it("should recompute when toggle values change", () => {
			const initialToggles = {
				alwaysAllowReadOnly: true,
				alwaysAllowWrite: false,
			}

			const { result, rerender } = renderHook(
				({ toggles, autoApprovalEnabled }) => useAutoApprovalState(toggles, autoApprovalEnabled),
				{
					initialProps: {
						toggles: initialToggles,
						autoApprovalEnabled: true,
					},
				},
			)

			expect(result.current.hasEnabledOptions).toBe(true)
			expect(result.current.effectiveAutoApprovalEnabled).toBe(true)

			// Change toggle values
			const newToggles = {
				alwaysAllowReadOnly: false,
				alwaysAllowWrite: false,
			}

			rerender({ toggles: newToggles, autoApprovalEnabled: true })

			expect(result.current.hasEnabledOptions).toBe(false)
			expect(result.current.effectiveAutoApprovalEnabled).toBe(true)
		})

		it("should recompute effectiveAutoApprovalEnabled when autoApprovalEnabled changes", () => {
			const toggles = {
				alwaysAllowReadOnly: true,
				alwaysAllowWrite: false,
			}

			const { result, rerender } = renderHook(
				({ toggles, autoApprovalEnabled }) => useAutoApprovalState(toggles, autoApprovalEnabled),
				{
					initialProps: {
						toggles,
						autoApprovalEnabled: true,
					},
				},
			)

			expect(result.current.effectiveAutoApprovalEnabled).toBe(true)

			rerender({ toggles, autoApprovalEnabled: false })

			expect(result.current.effectiveAutoApprovalEnabled).toBe(false)
		})
	})

	describe("edge cases", () => {
		it("should handle partial toggle objects", () => {
			const toggles = {
				alwaysAllowReadOnly: true,
				// Other properties are optional
			}

			const { result } = renderHook(() => useAutoApprovalState(toggles, true))

			expect(result.current.hasEnabledOptions).toBe(true)
			expect(result.current.effectiveAutoApprovalEnabled).toBe(true)
		})

		it("should handle empty toggle object", () => {
			const toggles = {}

			const { result } = renderHook(() => useAutoApprovalState(toggles, true))

			expect(result.current.hasEnabledOptions).toBe(false)
			expect(result.current.effectiveAutoApprovalEnabled).toBe(true)
		})

		it("should handle mixed truthy/falsy values correctly", () => {
			const toggles = {
				alwaysAllowReadOnly: 1 as any, // truthy non-boolean
				alwaysAllowWrite: "" as any, // falsy non-boolean
				alwaysAllowExecute: null as any, // falsy non-boolean
				alwaysAllowMcp: "yes" as any, // truthy non-boolean
			}

			const { result } = renderHook(() => useAutoApprovalState(toggles, true))

			expect(result.current.hasEnabledOptions).toBe(true) // Because some values are truthy
		})
	})
})

import React, { createContext, useContext, ReactNode, useEffect, useCallback } from "react"
import { useTranslation } from "react-i18next"
import i18next, { loadTranslations } from "./setup"
import { useExtensionState } from "@/context/ExtensionStateContext"

// Create context for translations
export const TranslationContext = createContext<{
	t: (key: string, options?: Record<string, any>) => string
	i18n: typeof i18next
}>({
	t: (key: string) => key,
	i18n: i18next,
})

// Translation provider component
export const TranslationProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
	// Initialize with default configuration
	const { i18n } = useTranslation()
	// Get the extension state directly - it already contains all state properties
	const extensionState = useExtensionState()

	// Load translations once when the component mounts
	useEffect(() => {
		try {
			loadTranslations()
		} catch (error) {
			console.error("Failed to load translations:", error)
		}
	}, [])

	useEffect(() => {
		i18n.changeLanguage(extensionState.language)
	}, [i18n, extensionState.language])

	// Memoize the translation function to prevent unnecessary re-renders
	const translate = useCallback(
		(key: string, options?: Record<string, any>) => {
			return i18n.t(key, options)
		},
		[i18n],
	)

	return (
		<TranslationContext.Provider
			value={{
				t: translate,
				i18n,
			}}>
			{children}
		</TranslationContext.Provider>
	)
}

// Custom hook for easy translations
export const useAppTranslation = () => useContext(TranslationContext)

export default TranslationProvider

