import { describe, expect, it } from "vitest"

import { ALERT_TYPES, countMarkdownHeadings, hasComplexMarkdown, remarkGithubAlerts } from "../markdown"

// Minimal mdast builders so we can exercise the plugin without a full parser.
const text = (value: string) => ({ type: "text", value })
const paragraph = (...children: any[]) => ({ type: "paragraph", children })
const blockquote = (...children: any[]) => ({ type: "blockquote", children })
const root = (...children: any[]) => ({ type: "root", children })

const transform = (tree: any) => {
	remarkGithubAlerts()(tree)
	return tree
}

describe("markdown heading helpers", () => {
	it("returns 0 for empty or undefined", () => {
		expect(countMarkdownHeadings(undefined)).toBe(0)
		expect(countMarkdownHeadings("")).toBe(0)
	})

	it("counts single and multiple headings", () => {
		expect(countMarkdownHeadings("# One")).toBe(1)
		expect(countMarkdownHeadings("# One\nContent")).toBe(1)
		expect(countMarkdownHeadings("# One\n## Two")).toBe(2)
		expect(countMarkdownHeadings("# One\n## Two\n### Three")).toBe(3)
	})

	it("handles all heading levels", () => {
		const md = `# h1\n## h2\n### h3\n#### h4\n##### h5\n###### h6`
		expect(countMarkdownHeadings(md)).toBe(6)
	})

	it("ignores headings inside code fences", () => {
		const md = "# real\n```\n# not a heading\n```\n## real"
		expect(countMarkdownHeadings(md)).toBe(2)
	})

	it("hasComplexMarkdown requires at least two headings", () => {
		expect(hasComplexMarkdown("# One")).toBe(false)
		expect(hasComplexMarkdown("# One\n## Two")).toBe(true)
	})
})

describe("remarkGithubAlerts", () => {
	it.each(ALERT_TYPES)("annotates a [!%s] alert blockquote", (type) => {
		const upper = type.toUpperCase()
		const tree = root(blockquote(paragraph(text(`[!${upper}]\nBody text`))))

		transform(tree)

		const bq = tree.children[0]
		expect(bq.data.hProperties["data-alert-type"]).toBe(type)
		expect(bq.data.hProperties.className).toBe(`markdown-alert markdown-alert-${type}`)

		// Marker is stripped from the rendered content.
		expect(bq.children[0].children[0].value).toBe("Body text")
	})

	it("recognizes markers case-insensitively", () => {
		const tree = root(blockquote(paragraph(text("[!Note]\nhi"))))

		transform(tree)

		expect(tree.children[0].data.hProperties["data-alert-type"]).toBe("note")
		expect(tree.children[0].children[0].children[0].value).toBe("hi")
	})

	it("removes the marker paragraph when it has no following inline content", () => {
		// `> [!NOTE]` on its own line followed by a separate paragraph.
		const tree = root(blockquote(paragraph(text("[!NOTE]\n")), paragraph(text("Body on next line"))))

		transform(tree)

		const bq = tree.children[0]
		expect(bq.data.hProperties["data-alert-type"]).toBe("note")
		// The emptied marker paragraph is dropped; body paragraph remains.
		expect(bq.children).toHaveLength(1)
		expect(bq.children[0].children[0].value).toBe("Body on next line")
	})

	it("leaves a normal blockquote untouched", () => {
		const tree = root(blockquote(paragraph(text("Just a quote, not an alert."))))

		transform(tree)

		const bq = tree.children[0]
		expect(bq.data).toBeUndefined()
		expect(bq.children[0].children[0].value).toBe("Just a quote, not an alert.")
	})

	it("ignores unsupported markers and renders them as normal blockquotes", () => {
		const tree = root(blockquote(paragraph(text("[!INFO]\nNot a real alert type"))))

		transform(tree)

		const bq = tree.children[0]
		expect(bq.data).toBeUndefined()
		expect(bq.children[0].children[0].value).toBe("[!INFO]\nNot a real alert type")
	})

	it("does not treat a marker in the middle of text as an alert", () => {
		const tree = root(blockquote(paragraph(text("Some text [!NOTE] still a quote"))))

		transform(tree)

		expect(tree.children[0].data).toBeUndefined()
	})

	it("annotates nested alert blockquotes", () => {
		const tree = root(blockquote(blockquote(paragraph(text("[!TIP]\nnested")))))

		transform(tree)

		const inner = tree.children[0].children[0]
		expect(inner.data.hProperties["data-alert-type"]).toBe("tip")
	})
})

import { ReactNode } from "react"
import { getHighlighter } from "./highlighter"
import { toJsxRuntime } from "hast-util-to-jsx-runtime"
import { Fragment, jsx, jsxs } from "react/jsx-runtime"

/**
 * Highlight two pieces of code (old and new) in a single pass and return
 * arrays of ReactNode representing each line
 */
export async function highlightHunks(
	oldText: string,
	newText: string,
	lang: string,
	theme: "light" | "dark",
	_hunkIndex = 0,
	_filePath?: string,
): Promise<{ oldLines: ReactNode[]; newLines: ReactNode[] }> {
	try {
		const highlighter = await getHighlighter(lang)
		const shikiTheme = theme === "light" ? "github-light" : "github-dark"

		// Helper to highlight text and extract lines
		const highlightAndExtractLines = (text: string): ReactNode[] => {
			const textLines = text.split("\n")

			if (!text.trim()) {
				return textLines.map((line) => line || "")
			}

			try {
				// Use Shiki's line transformer to get per-line highlighting
				const hast: any = highlighter.codeToHast(text, {
					lang,
					theme: shikiTheme,
					transformers: [
						{
							pre(node: any) {
								node.properties.style = "padding:0;margin:0;background:none;"
								return node
							},
							code(node: any) {
								node.properties.class = `hljs language-${lang}`
								return node
							},
							line(node: any, line: number) {
								// Add a line marker to help with extraction
								node.properties["data-line"] = line
								return node
							},
						},
					],
				})

				// Extract the <code> element's children (which should be line elements)
				const codeEl = hast?.children?.[0]?.children?.[0]
				if (!codeEl || !codeEl.children) {
					return textLines.map((line) => line || "")
				}

				// Convert each line element to a ReactNode
				const highlightedLines: ReactNode[] = []

				for (const lineNode of codeEl.children) {
					if (lineNode.tagName === "span" && lineNode.properties?.className?.includes("line")) {
						// This is a line span from Shiki
						const reactNode = toJsxRuntime(
							{ type: "element", tagName: "span", properties: {}, children: lineNode.children || [] },
							{ Fragment, jsx, jsxs },
						)
						highlightedLines.push(reactNode)
					}
				}

				// If we didn't get the expected structure, fall back to simple approach
				if (highlightedLines.length !== textLines.length) {
					// For each line, highlight it individually (fallback)
					return textLines.map((line) => {
						if (!line.trim()) return line

						try {
							const lineHast: any = highlighter.codeToHast(line, {
								lang,
								theme: shikiTheme,
								transformers: [
									{
										pre(node: any) {
											node.properties.style = "padding:0;margin:0;background:none;"
											return node
										},
										code(node: any) {
											node.properties.class = `hljs language-${lang}`
											return node
										},
									},
								],
							})

							const lineCodeEl = lineHast?.children?.[0]?.children?.[0]
							if (!lineCodeEl || !lineCodeEl.children) {
								return line
							}

							return toJsxRuntime(
								{ type: "element", tagName: "span", properties: {}, children: lineCodeEl.children },
								{ Fragment, jsx, jsxs },
							)
						} catch {
							return line
						}
					})
				}

				return highlightedLines
			} catch {
				return textLines.map((line) => line || "")
			}
		}

		// Process both old and new text
		const oldLines = highlightAndExtractLines(oldText)
		const newLines = highlightAndExtractLines(newText)

		return { oldLines, newLines }
	} catch {
		// Fallback to plain text on any error
		return {
			oldLines: oldText.split("\n").map((line) => line || ""),
			newLines: newText.split("\n").map((line) => line || ""),
		}
	}
}

import { visit } from "unist-util-visit"

/**
 * Counts the number of markdown headings in the given text.
 * Matches headings from level 1 to 6 (e.g. #, ##, ###, etc.).
 * Code fences are stripped before matching to avoid false positives.
 */
export function countMarkdownHeadings(text: string | undefined): number {
	if (!text) return 0

	// Remove fenced code blocks to avoid counting headings inside code
	const withoutCodeBlocks = text.replace(/```[\s\S]*?```/g, "")

	// Up to 3 leading spaces are allowed before the hashes per the markdown spec
	const headingRegex = /^\s{0,3}#{1,6}\s+.+$/gm
	const matches = withoutCodeBlocks.match(headingRegex)
	return matches ? matches.length : 0
}

/**
 * Returns true if the markdown contains at least two headings.
 */
export function hasComplexMarkdown(text: string | undefined): boolean {
	return countMarkdownHeadings(text) >= 2
}

/**
 * GitHub-style Markdown alert types, mapped to their lower-cased identifiers.
 * @see https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax#alerts
 */
export const ALERT_TYPES = ["note", "tip", "important", "warning", "caution"] as const

export type AlertType = (typeof ALERT_TYPES)[number]

// Matches a leading alert marker like "[!NOTE]" (case-insensitive) optionally
// followed by trailing whitespace/newline on the first line of a blockquote.
const ALERT_MARKER_REGEX = new RegExp(`^\\[!(${ALERT_TYPES.join("|")})\\][^\\S\\r\\n]*\\r?\\n?`, "i")

/**
 * remark plugin that detects GitHub-style alerts inside blockquotes
 * (e.g. `> [!NOTE]`) and annotates the blockquote node so it can be rendered
 * as a distinct alert block.
 *
 * The marker text is stripped from the rendered content and the recognized
 * alert type is exposed via the `data-alert-type` attribute plus matching
 * `markdown-alert*` class names on the emitted `<blockquote>` element.
 *
 * Blockquotes that do not begin with a supported marker are left untouched, so
 * normal blockquotes continue to render exactly as before.
 */
export function remarkGithubAlerts() {
	return (tree: Parameters<typeof visit>[0]) => {
		visit(tree, "blockquote", annotateAlertBlockquote)
	}
}

function annotateAlertBlockquote(node: any): void {
	const firstChild = node.children?.[0]

	// The marker must live in the first paragraph's first text node.
	if (!firstChild || firstChild.type !== "paragraph") {
		return
	}

	const firstText = firstChild.children?.[0]

	if (!firstText || firstText.type !== "text" || typeof firstText.value !== "string") {
		return
	}

	const match = firstText.value.match(ALERT_MARKER_REGEX)

	if (!match) {
		return
	}

	const alertType = match[1].toLowerCase() as AlertType

	// Strip the marker (and the following newline) from the rendered content.
	firstText.value = firstText.value.slice(match[0].length)

	// Drop the now-empty leading text node so the alert body starts cleanly.
	if (firstText.value === "") {
		firstChild.children.shift()
	}

	// If the paragraph became empty (marker was on its own line with no inline
	// content following it), remove it entirely.
	if (firstChild.children.length === 0) {
		node.children.shift()
	}

	node.data = node.data || {}
	const hProperties = (node.data.hProperties = node.data.hProperties || {})
	hProperties.className = `markdown-alert markdown-alert-${alertType}`
	hProperties["data-alert-type"] = alertType
}

import { parsePatch } from "diff"

export interface DiffLine {
	oldLineNum: number | null
	newLineNum: number | null
	type: "context" | "addition" | "deletion" | "gap"
	content: string
	hiddenCount?: number
}

/**
 * Parse a unified diff string into a flat list of renderable lines with
 * line numbers, addition/deletion/context flags, and compact "gap" separators
 * between hunks.
 */
export function parseUnifiedDiff(source: string, filePath?: string): DiffLine[] {
	if (!source) return []

	try {
		const patches = parsePatch(source)
		if (!patches || patches.length === 0) return []

		const patch = filePath
			? (patches.find((p) =>
					[p.newFileName, p.oldFileName].some(
						(n) => typeof n === "string" && (n === filePath || (n as string).endsWith("/" + filePath)),
					),
				) ?? patches[0])
			: patches[0]

		if (!patch) return []

		const lines: DiffLine[] = []
		let prevHunk: any = null
		for (const hunk of (patch as any).hunks || []) {
			// Insert a compact "hidden lines" separator between hunks
			if (prevHunk) {
				const gapNew = hunk.newStart - (prevHunk.newStart + prevHunk.newLines)
				const gapOld = hunk.oldStart - (prevHunk.oldStart + prevHunk.oldLines)
				const hidden = Math.max(gapNew, gapOld)
				if (hidden > 0) {
					lines.push({
						oldLineNum: null,
						newLineNum: null,
						type: "gap",
						content: "",
						hiddenCount: hidden,
					})
				}
			}

			let oldLine = hunk.oldStart
			let newLine = hunk.newStart

			for (const raw of hunk.lines || []) {
				const firstChar = (raw as string)[0]
				const content = (raw as string).slice(1)

				if (firstChar === "-") {
					lines.push({
						oldLineNum: oldLine,
						newLineNum: null,
						type: "deletion",
						content,
					})
					oldLine++
				} else if (firstChar === "+") {
					lines.push({
						oldLineNum: null,
						newLineNum: newLine,
						type: "addition",
						content,
					})
					newLine++
				} else {
					// Context line
					lines.push({
						oldLineNum: oldLine,
						newLineNum: newLine,
						type: "context",
						content,
					})
					oldLine++
					newLine++
				}
			}

			prevHunk = hunk
		}

		return lines
	} catch {
		// swallow parse errors and render nothing rather than breaking the UI
		return []
	}
}

/**
 * Source Map Initializer
 *
 * This utility ensures source maps are properly loaded in production builds.
 * It attempts to preload source maps for all scripts on the page and
 * sets up global error handlers to enhance errors with source maps.
 *
 * This implementation is compatible with VSCode's Content Security Policy.
 */

import { enhanceErrorWithSourceMaps } from "./sourceMapUtils"

/**
 * Initialize source map support for production builds
 */
export function initializeSourceMaps(): void {
	if (process.env.NODE_ENV !== "production") {
		// Only needed in production builds
		return
	}

	console.debug("Initializing CSP-compatible source map support for production build")

	// Set up global error handler
	window.addEventListener("error", async (event) => {
		if (event.error && event.error instanceof Error) {
			try {
				// Apply source maps to the error
				const enhancedError = await enhanceErrorWithSourceMaps(event.error)

				// Log the enhanced error
				console.error("Source mapped error:", enhancedError)

				// Don't prevent default handling - let the ErrorBoundary catch it
			} catch (e) {
				console.error("Error enhancing error with source maps:", e)
			}
		}
	})

	// Set up unhandled promise rejection handler
	window.addEventListener("unhandledrejection", async (event) => {
		if (event.reason && event.reason instanceof Error) {
			try {
				// Apply source maps to the error
				const enhancedError = await enhanceErrorWithSourceMaps(event.reason)

				// Log the enhanced error
				console.error("Source mapped rejection:", enhancedError)
			} catch (e) {
				console.error("Error enhancing rejection with source maps:", e)
			}
		}
	})

	// Preload source maps for all scripts
	try {
		const scripts = document.getElementsByTagName("script")
		for (let i = 0; i < scripts.length; i++) {
			const script = scripts[i]
			if (script.src) {
				// Try multiple source map locations
				const possibleMapUrls = [
					`${script.src}.map`,
					`${script.src}?source-map=true`,
					script.src.replace(/\.js$/, ".js.map"),
					script.src.replace(/\.js$/, ".map.json"),
					script.src.replace(/\.js$/, ".sourcemap"),
				]

				// Preload all possible source map locations
				for (const mapUrl of possibleMapUrls) {
					const link = document.createElement("link")
					link.rel = "preload"
					link.as = "fetch"
					link.href = mapUrl
					link.crossOrigin = "anonymous"
					document.head.appendChild(link)
				}

				// Also check for inline sourceMappingURL comments
				fetch(script.src)
					.then((response) => response.text())
					.then((content) => {
						const sourceMappingURLMatch = content.match(/\/\/[#@]\s*sourceMappingURL=([^\s]+)/)
						if (sourceMappingURLMatch && sourceMappingURLMatch[1]) {
							const sourceMappingURL = sourceMappingURLMatch[1]

							// If it's not a data: URL, preload it
							if (!sourceMappingURL.startsWith("data:")) {
								const scriptUrlObj = new URL(script.src)
								const baseUrl = scriptUrlObj.href.substring(0, scriptUrlObj.href.lastIndexOf("/") + 1)
								const fullUrl = new URL(sourceMappingURL, baseUrl).href

								const link = document.createElement("link")
								link.rel = "preload"
								link.as = "fetch"
								link.href = fullUrl
								link.crossOrigin = "anonymous"
								document.head.appendChild(link)
							}
						}
					})
					.catch((e) => console.debug("Error checking for inline sourceMappingURL:", e))
			}
		}
	} catch (e) {
		console.error("Error preloading source maps:", e)
	}
}

/**
 * Expose source maps on the window object for debugging
 */
export function exposeSourceMapsForDebugging(): void {
	if (process.env.NODE_ENV !== "production") {
		return
	}

	try {
		// Add a global function to manually apply source maps to an error
		;(window as any).__applySourceMaps = async (error: Error) => {
			if (!(error instanceof Error)) {
				console.error("Not an Error object:", error)
				return error
			}
			return await enhanceErrorWithSourceMaps(error)
		}

		// Add a global function to test source map functionality
		;(window as any).__testSourceMaps = () => {
			try {
				// Intentionally cause an error
				const obj: any = undefined
				obj.nonExistentMethod()
			} catch (e) {
				if (e instanceof Error) {
					console.log("Original error:", e)
					;(window as any).__applySourceMaps(e).then((enhanced: Error) => {
						console.log("Enhanced error:", enhanced)

						// Log the source mapped stack if available
						if ("sourceMappedStack" in enhanced) {
							console.log("Source mapped stack:", enhanced.sourceMappedStack)
						}

						// Log the source mapped component stack if available
						if ("sourceMappedComponentStack" in enhanced) {
							console.log("Source mapped component stack:", enhanced.sourceMappedComponentStack)
						}
					})
				}
			}
		}

		// Add a global function to check if source maps are available for a script
		;(window as any).__checkSourceMap = async (scriptUrl: string) => {
			try {
				const response = await fetch(`${scriptUrl}.map`)
				if (response.ok) {
					const sourceMap = await response.json()
					const originalFileName =
						sourceMap.sources && sourceMap.sources.length > 0 ? sourceMap.sources[0] : "unknown"
					console.log(`Source map found for ${scriptUrl}. Original file: ${originalFileName}`)
					return true
				} else {
					console.log(`No source map found for ${scriptUrl}`)
					return false
				}
			} catch (e) {
				console.error(`Error checking source map for ${scriptUrl}:`, e)
				return false
			}
		}

		console.debug("Source map debugging utilities exposed on window object")
	} catch (e) {
		console.error("Error exposing source maps for debugging:", e)
	}
}

import * as StackTrace from "stacktrace-js"

/**
 * Extended Error interface with source mapped stack trace
 */
export interface EnhancedError extends Error {
	sourceMappedStack?: string
	sourceMappedComponentStack?: string
}

/**
 * Apply source maps to a stack trace using StackTrace.js
 * Returns the original stack trace if source maps can't be applied
 */
export async function applySourceMapsToStack(stack: string): Promise<string> {
	if (!stack) {
		console.debug("applySourceMapsToStack: Empty stack trace provided")
		return stack
	}

	console.debug("Original stack trace:", stack)

	try {
		// Create a temporary Error object with the provided stack
		const tempError = new Error()
		tempError.stack = stack

		// Extract the error message (first line)
		const errorMessage = stack.split("\n")[0]
		console.debug("Error message:", errorMessage)

		// Use StackTrace.js to get source mapped stack frames
		const stackFrames = await StackTrace.fromError(tempError)
		console.debug("StackTrace.js parsed frames:", stackFrames)

		// Convert stack frames back to string format
		const mappedFrames = stackFrames.map((frame: StackTrace.StackFrame) => {
			const functionName = frame.functionName || "<anonymous>"
			const fileName = frame.fileName || "unknown"
			const lineNumber = frame.lineNumber || 0
			const columnNumber = frame.columnNumber || 0

			return `    at ${functionName} (${fileName}:${lineNumber}:${columnNumber})`
		})

		// Reconstruct the stack trace with the error message
		const result = [errorMessage, ...mappedFrames].join("\n")
		console.debug("Final mapped stack trace:", result)
		return result
	} catch (error) {
		console.error("Error applying source maps with StackTrace.js:", error)
		return stack // Return original stack on error
	}
}

/**
 * Apply source maps to a React component stack trace using StackTrace.js
 */
export async function applySourceMapsToComponentStack(componentStack: string): Promise<string> {
	if (!componentStack) {
		console.debug("applySourceMapsToComponentStack: Empty component stack provided")
		return componentStack
	}

	console.debug("Original component stack:", componentStack)

	try {
		// Component stack has a different format than error stack
		// Example: at ComponentName (file:///path/to/file.tsx:123:45)
		const lines = componentStack.split("\n")
		const mappedLines = await Promise.all(
			lines.map(async (line) => {
				// Skip empty lines
				if (!line.trim()) return line

				// Extract file path, line and column numbers
				const match = line.match(/at\s+(.+?)\s+\((.+?):(\d+):(\d+)\)/)
				if (!match) return line

				const [_, componentName, fileName, lineNumber, columnNumber] = match
				console.debug(`Processing component stack line:`, { componentName, fileName, lineNumber, columnNumber })

				try {
					// Create a synthetic stack frame for StackTrace.js
					const syntheticError = new Error()
					syntheticError.stack = `Error\n    at ${componentName} (${fileName}:${lineNumber}:${columnNumber})`

					// Use StackTrace.js to resolve source maps
					const stackFrames = await StackTrace.fromError(syntheticError)

					if (stackFrames.length > 0) {
						const frame = stackFrames[0]
						const mappedFileName = frame.fileName || fileName
						const mappedLineNumber = frame.lineNumber || parseInt(lineNumber, 10)
						const mappedColumnNumber = frame.columnNumber || parseInt(columnNumber, 10)

						return `at ${componentName} (${mappedFileName}:${mappedLineNumber}:${mappedColumnNumber})`
					}
				} catch (e) {
					console.debug(`Error processing component stack line with StackTrace.js:`, e)
				}

				return line
			}),
		)

		const result = mappedLines.join("\n")
		console.debug("Final mapped component stack:", result)
		return result
	} catch (error) {
		console.error("Error applying source maps to component stack with StackTrace.js:", error)
		return componentStack
	}
}

/**
 * Enhance an Error object with source mapped stack trace and component stack
 */
export function enhanceErrorWithSourceMaps(error: Error, componentStack?: string): Promise<EnhancedError> {
	console.debug("Enhancing error with source maps using StackTrace.js:", error)

	return new Promise<EnhancedError>((resolve) => {
		if (!error.stack) {
			console.debug("Error has no stack trace")
			resolve(error as EnhancedError)
			return
		}

		// Process both stacks in parallel
		const stackPromise = applySourceMapsToStack(error.stack)
		const componentStackPromise = componentStack
			? applySourceMapsToComponentStack(componentStack)
			: Promise.resolve(undefined)

		Promise.all([stackPromise, componentStackPromise])
			.then(([sourceMappedStack, sourceMappedComponentStack]) => {
				console.debug("Source mapped stacks applied successfully with StackTrace.js")

				// Extend the error object with the source mapped stack
				Object.defineProperty(error, "sourceMappedStack", {
					value: sourceMappedStack,
					writable: true,
					configurable: true,
				})

				// Add the source mapped component stack if available
				if (sourceMappedComponentStack) {
					Object.defineProperty(error, "sourceMappedComponentStack", {
						value: sourceMappedComponentStack,
						writable: true,
						configurable: true,
					})
				}

				resolve(error)
			})
			.catch((mapError) => {
				console.error("Error applying source maps with StackTrace.js:", mapError)
				// If anything fails, just return the original error
				resolve(error)
			})
	})
}

/**
 * Parse a stack trace string into structured stack frames
 * This is kept for backward compatibility with tests
 */
export async function parseStackTrace(stack: string): Promise<any[]> {
	if (!stack) return []

	try {
		// Create a temporary Error object with the provided stack
		const tempError = new Error()
		tempError.stack = stack

		// Use StackTrace.js to parse the stack
		const frames = await StackTrace.fromError(tempError)
		return frames.map((frame: StackTrace.StackFrame) => ({
			functionName: frame.functionName || "<anonymous>",
			fileName: frame.fileName,
			lineNumber: frame.lineNumber,
			columnNumber: frame.columnNumber,
			source: `at ${frame.functionName || "<anonymous>"} (${frame.fileName}:${frame.lineNumber}:${frame.columnNumber})`,
		}))
	} catch (error) {
		console.error("Error parsing stack trace with StackTrace.js:", error)
		return [] // Return empty array if parsing fails
	}
}

